?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END < 1000 OR (stores.delivery_mode = 'walking' AND CASE WHEN stores.latitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END <= 1000) THEN 1.00000000000000000E0 WHEN CASE WHEN stores.latitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END < 2000 THEN 2.00000000000000000E0 ELSE CASE WHEN stores.latitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END / 1000E0 END) * 1.30000000000000004E0 / (CASE stores.delivery_mode WHEN 'walking' THEN 5.00000000000000000E0 WHEN 'bicycle' THEN 12.00000000000000000E0 WHEN 'motorcycle' THEN 25.00000000000000000E0 ELSE 20.00000000000000000E0 END) * 60E0, 6)) END + 1.00000000000000000E0 + (10.00000000000000000E0 / 60E0)) + 1.00000000000000000E0 + 2.00000000000000000E0 + 0, 4) / 2.00000000000000000E0) * 2.00000000000000000E0) END) as eta_upper_minutes, (select count(*) from `items` where `stores`.`id` = `items`.`store_id`) as `items_count`, (select count(*) from `campaigns` inner join `campaign_store` on `campaigns`.`id` = `campaign_store`.`campaign_id` where `stores`.`id` = `campaign_store`.`store_id`) as `campaigns_count`, (select count(*) from `reviews` inner join `items` on `items`.`id` = `reviews`.`item_id` where `stores`.`id` = `items`.`store_id`) as `reviews_count`, (select count(*) from `orders` where `stores`.`id` = `orders`.`store_id`) as `orders_count`, exists(select * from `items` where `stores`.`id` = `items`.`store_id` and `discount` > 0) as `discount_status`, (select min(`items`.`price`) from `items` where `stores`.`id` = `items`.`store_id` and `status` = 1 and `is_approved` = 1 and exists (select * from `stores` where `items`.`store_id` = `stores`.`id` and `status` = 1 and (`store_business_model` = 'commission' or exists (select * from `store_subscriptions` inner join (select MAX(`store_subscriptions`.`id`) as `id_aggregate`, `store_subscriptions`.`store_id` from `store_subscriptions` group by `store_subscriptions`.`store_id`) as `latestOfMany` on `latestOfMany`.`id_aggregate` = `store_subscriptions`.`id` and `latestOfMany`.`store_id` = `store_subscriptions`.`store_id` where `stores`.`id` = `store_subscriptions`.`store_id` and (`max_order` = 'unlimited' or `max_order` > 0) and `status` = 1)))) as `items_min_price`, (select max(`items`.`price`) from `items` where `stores`.`id` = `items`.`store_id` and `status` = 1 and `is_approved` = 1 and exists (select * from `stores` where `items`.`store_id` = `stores`.`id` and `status` = 1 and (`store_business_model` = 'commission' or exists (select * from `store_subscriptions` inner join (select MAX(`store_subscriptions`.`id`) as `id_aggregate`, `store_subscriptions`.`store_id` from `store_subscriptions` group by `store_subscriptions`.`store_id`) as `latestOfMany` on `latestOfMany`.`id_aggregate` = `store_subscriptions`.`id` and `latestOfMany`.`store_id` = `store_subscriptions`.`store_id` where `stores`.`id` = `store_subscriptions`.`store_id` and (`max_order` = 'unlimited' or `max_order` > 0) and `status` = 1)))) as `items_max_price` from `stores` where exists (select * from `modules` where `stores`.`module_id` = `modules`.`id` and `status` = 1) and `status` = 1 and (`store_business_model` = 'commission' or exists (select * from `store_subscriptions` inner join (select MAX(`store_subscriptions`.`id`) as `id_aggregate`, `store_subscriptions`.`store_id` from `store_subscriptions` group by `store_subscriptions`.`store_id`) as `latestOfMany` on `latestOfMany`.`id_aggregate` = `store_subscriptions`.`id` and `latestOfMany`.`store_id` = `store_subscriptions`.`store_id` where `stores`.`id` = `store_subscriptions`.`store_id` and (`max_order` = 'unlimited' or `max_order` > 0) and `status` = 1)) and `stores`.`active` = 1 and exists (select * from `zones` where `stores`.`zone_id` = `zones`.`id` and exists (select * from `modules` inner join `module_zone` on `modules`.`id` = `module_zone`.`module_id` where `zones`.`id` = `module_zone`.`zone_id` and `modules`.`id` = 2)) and `module_id` = 2 and `zone_id` in (2) and NOT (stores.delivery_mode = 'walking' AND COALESCE(CASE WHEN stores.latitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND stores.longitude REGEXP '^-?[0-9]+([.][0-9]+)?$' AND CAST(stores.latitude AS DECIMAL(10,7)) BETWEEN -90 AND 90 AND CAST(stores.longitude AS DECIMAL(11,7)) BETWEEN -180 AND 180 THEN ST_Distance_Sphere(point(stores.longitude, stores.latitude), point(54.37734379999999845E0, 24.45388399999999862E0)) END > 1000.00000000000000000E0, 0)) order by `open` desc, `id` asc limit 25 offset 0;
